// The eight-point "spark" that precedes the flavour name on current Sprite cans.
function spark(cx, cy, r) {
  const pts = [[-82, 1], [-38, .7], [4, .86], [48, .68], [98, .96], [147, .7], [186, .84], [222, .72]];
  const p = (deg, k) => [r2(cx + Math.cos(deg * Math.PI / 180) * r * k * .8), r2(cy + Math.sin(deg * Math.PI / 180) * r * k)];
  let d = '';
  pts.forEach(([a, k], i) => {
    const [na] = pts[(i + 1) % pts.length]; const mid = (a + (na < a ? na + 360 : na)) / 2;
    const [x, y] = p(a, k); const [qx, qy] = p(mid, .34); const [ex, ey] = p(na, pts[(i + 1) % pts.length][1]);
    d += `${i ? '' : `M${x} ${y}`}Q${qx} ${qy} ${ex} ${ey}`;
  });
  return d + 'Z';
}
// Both cans: the same green, the wordmark across the upper half and cropped by both edges, and
// a small spark + LEMON-LIME low on the left. Only the inks differ.
const spriteCan = (slug, title, ink, extra, lemon) => can(slug, title, `
<path d="${SPRITE_WORDMARK}" fill="${ink}" fill-rule="evenodd"/>
${extra}
<path d="${spark(59.6, 183.9, 4.4)}" fill="${ink === '#fff' ? '#eef3ee' : ink}"/>
<path d="${lemon}" fill="#e9df1b" fill-rule="evenodd"/>
`, '#06a535', '', { speckle: false, bar: .14 });
const sprite = spriteCan('sprite', 'Sprite', '#fff', '', SPRITE_LEMON);
const spriteZero = spriteCan('sprite-zero-sugar', 'Sprite Zero Sugar', '#101410',
  `<path d="${SPRITE_ZERO}" fill="#101410" fill-rule="evenodd" transform="translate(0 -7.5)"/>`, SPRITE_ZLEMON);

